#!/usr/bin/env bash
# Capture desktop + mobile screenshots of CAPTURE_URL into CAPTURE_DIR.
# Leaves the app server running; closes only its own browser.
# Exit 75 = temporary navigation/browser infrastructure failure; exit 1 = script/rendering defect.
set -euo pipefail
cd "$(dirname "$0")"
if [[ -z "${CAPTURE_URL:-}" || -z "${CAPTURE_DIR:-}" ]]; then
  echo "Set CAPTURE_URL and CAPTURE_DIR." >&2
  exit 1
fi
/usr/bin/time -p mkdir -p "$CAPTURE_DIR"
/usr/bin/time -p node -e 'const fs=require("fs"),path=require("path"),os=require("os");const url=process.env.CAPTURE_URL,out=process.env.CAPTURE_DIR;if(!url||!out){console.error("Set CAPTURE_URL and CAPTURE_DIR.");process.exit(1);}const runtime=path.join(os.homedir(),".local","share","omgithub-playwright");const req=require("module").createRequire(path.join(runtime,"package.json"));const chromium=req("playwright").chromium;const cfg=JSON.parse(fs.readFileSync(path.join(runtime,process.platform==="darwin"?"metal.json":"linux.json"),"utf8"));if(process.platform==="linux"&&!process.env.DISPLAY){try{process.env.DISPLAY=":"+fs.readFileSync(path.join(runtime,"display"),"utf8").trim();}catch(e){console.error("no X display file");process.exit(75);}}(async()=>{let browser,code=0;try{try{browser=await chromium.launch(Object.assign({},cfg.browser.launchOptions,{timeout:30000}));}catch(e){throw Object.assign(new Error("browser launch failed: "+e.message),{code:75});}for(const v of [["desktop",1440,900],["mobile",390,844]]){const name=v[0],width=v[1],height=v[2];let page;try{page=await browser.newPage({viewport:{width:width,height:height}});}catch(e){throw Object.assign(new Error("newPage failed ("+name+"): "+e.message),{code:75});}page.setDefaultTimeout(30000);page.on("pageerror",e=>console.error("["+name+"] pageerror: "+e.message));let resp;try{resp=await page.goto(url,{waitUntil:"load",timeout:45000});}catch(e){throw Object.assign(new Error("navigation failed ("+name+"): "+e.message),{code:75});}const status=resp?resp.status():0;if(!resp||!resp.ok()){const t=!resp||[408,429,500,502,503,504].indexOf(status)>=0;throw Object.assign(new Error("HTTP "+status+" loading preview ("+name+")"),{code:t?75:1});}try{await page.locator("body").waitFor({state:"visible",timeout:15000});await page.waitForFunction(()=>document.fonts.status==="loaded",null,{timeout:15000});await page.locator("#startScreen").waitFor({state:"visible",timeout:15000});const btn=page.locator("#playBtn");if(await btn.count()>0&&(await btn.isVisible())){await btn.click({timeout:5000});await page.waitForFunction(()=>window.__gameStarted===true,null,{timeout:15000});}await page.waitForTimeout(4000);let errBox=false;try{errBox=await page.locator("#errorBox").isVisible();}catch(e){errBox=false;}if(errBox){throw Object.assign(new Error("app showed error box ("+name+")"),{code:1});}}catch(e){if(e&&e.code===1){throw e;}throw Object.assign(new Error("render wait failed ("+name+"): "+(e&&e.message)),{code:1});}const file=path.join(out,"final-"+name+".png");try{await page.screenshot({path:file,timeout:30000});}catch(e){const t=e.name==="TimeoutError"||!browser.isConnected();throw Object.assign(new Error("screenshot failed ("+name+"): "+e.message),{code:t?75:1});}const st=fs.statSync(file);console.log("captured "+file+" ("+st.size+" bytes)");if(st.size<15000){throw Object.assign(new Error("screenshot too small, likely blank ("+name+")"),{code:1});}await page.close();}}catch(e){console.error((e&&e.message)||e);code=(e&&e.code)||1;}try{if(browser){await browser.close();}}catch(e){console.error("browser close failed: "+e.message);code=code||75;}process.exit(code);})();'
